<?php
$localInput=static function(string $key,string $label,string $type='text',int $max=300,string $default='')use($p){$val=$p[$key]??$default;?><label><?=e($label)?><input name="<?=e($key)?>" type="<?=e($type)?>" value="<?=e($val)?>" <?=$key==='business_name'?'required':''?> <?php if($type==='number'):?>min="<?=$key==='rating'?1:0?>" max="<?=$key==='rating'?5:10000000?>" step="<?=$key==='rating'?'0.01':'1'?>"<?php elseif($type==='date'):?>max="<?=date('Y-m-d')?>"<?php else:?>maxlength="<?=$max?>"<?php endif;?>></label><?php };
$localArea=static function(string $key,string $label,int $max=3000,int $rows=3)use($p){$value=$p[$key]??'';if(is_array($value))$value=implode("\n",$value);?><label><?=e($label)?><textarea name="<?=e($key)?>" rows="<?=$rows?>" maxlength="<?=$max?>"><?=e($value)?></textarea></label><?php };
?>
<form data-api="local-seo-audit" id="local-profile-form"><input type="hidden" name="admin_context" value="<?=($localSeoRoute??'')==='/admin/local-seo'?'1':'0'?>"><input type="hidden" name="website_id" value="<?=$wid?>">
<div class="local-seo-form-block"><h3>1. Business profile</h3><p class="small">Use the details shown on your profile. Leave unknown values blank; only the business name is required.</p><div class="form-grid">
<?php $localInput('business_name','Business name','text',190);$localInput('category','Primary business category','text',100);select_field('business_type','Business type',['storefront'=>'Storefront · customers visit this address','service_area'=>'Service area · hide the street address','hybrid'=>'Hybrid · storefront and service area'],$p['business_type']??'storefront');$localInput('phone','Business phone · include country code','tel',40);$localInput('website','Business website','url',1000,$w['domain']);$localInput('profile_url','Google Business Profile link · optional','url',1000);?>
</div><?php $localArea('description','Business description',1500);$localArea('secondary_categories','Additional categories · one per line, up to 10',2000,2);?>
<h3>Location</h3><p class="small">For service-area businesses, the public service area is used for scoring and schema. Entered street details are stored in the private audit but omitted from generated schema.</p><div class="form-grid"><?php $localInput('street','Street address','text',300);$localInput('city','City / locality','text',100);$localInput('region','State / region','text',100);$localInput('postal_code','Postal code','text',30);$localInput('country','Two-letter country code · e.g. IN or US','text',2);$localInput('service_area','Service area · e.g. Pune and nearby towns','text',300);?></div>
</div>
<details class="local-seo-input-group"><summary>2. Reviews, photos &amp; services</summary><p class="small">Enter counts from the same profile and point in time. Blank means unknown; zero means none.</p><div class="form-grid"><?php $localInput('rating','Average rating · 1 to 5','number');$localInput('review_count','Total reviews','number');$localInput('replied_reviews','Reviews with a business reply','number');$localInput('last_review_date','Date of most recent review','date');$localInput('photo_count','Profile photo count','number');$localInput('image_url','Public business image URL · for schema','url',1000);?></div><?php $localArea('services','Services · one per line, up to 30',6000,4);?></details>
<details class="local-seo-input-group"><summary>3. Weekly opening hours</summary><p class="small">Choose a state for each day. Closing earlier than opening represents an overnight schedule. Special dates and split shifts should be added to the final schema manually.</p>
<?php foreach(LocalSeo::DAYS as $day):$hours=$p['hours'][$day]??['state'=>'unknown','opens'=>'','closes'=>''];?><div class="local-hours" data-local-hours><strong><?=e($day)?></strong><label>Status<select name="hours[<?=e($day)?>][state]" data-hours-state><?php foreach(['unknown'=>'Not entered','open'=>'Open · set times','closed'=>'Closed','all_day'=>'Open 24 hours'] as $value=>$label):?><option value="<?=$value?>" <?=$hours['state']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Opens<input type="time" name="hours[<?=e($day)?>][opens]" value="<?=e($hours['opens'])?>" data-hours-time></label><label>Closes<input type="time" name="hours[<?=e($day)?>][closes]" value="<?=e($hours['closes'])?>" data-hours-time></label></div><?php endforeach;?>
</details>
<details class="local-seo-input-group"><summary>4. NAP consistency · Name, Address, Phone</summary><p class="small">Paste the full details from your website and one directory. Include city, region, postal code and country in the address. For service-area businesses, enter the public service area instead. This compares only the text you supply; it does not search other sites.</p>
