<h3>Details on a directory</h3><div class="form-grid"><?php $localInput('directory_source','Directory name / source · e.g. Bing Places','text',200);$localInput('directory_name','Name on directory','text',190);$localInput('directory_phone','Phone on directory','tel',40);?></div><?php $localArea('directory_address','Full address or service area on directory',700,2);?></details>
